// post.service.ts
@Injectable({ providedIn: 'root' })
export class PostService {
  constructor(private http: HttpClient) {}

  getPosts(): Observable<Post[]> {
    return this.http.get<Post[]>('https://jsonplaceholder.typicode.com/posts').pipe(
      catchError(err => throwError(() => 'Error fetching posts'))
    );
  }

  createPost(post: Partial<Post>): Observable<Post> {
    return this.http.post<Post>('https://jsonplaceholder.typicode.com/posts', post).pipe(
      catchError(err => throwError(() => 'Error creating post'))
    );
  }

  deletePost(id: number): Observable<void> {
    return this.http.delete<void>(`https://jsonplaceholder.typicode.com/posts/${id}`).pipe(
      catchError(err => throwError(() => 'Error deleting post'))
    );
  }
}

// post-list.component.ts
export class PostListComponent implements OnInit {
  posts: Post[] = [];
  errorMessage = '';

  constructor(private postService: PostService) {}

  ngOnInit() {
    this.postService.getPosts().subscribe({
      next: posts => this.posts = posts,
      error: err => this.errorMessage = err
    });
  }

  addPost(title: string, body: string) {
    this.postService.createPost({ title, body }).subscribe({
      next: newPost => this.posts.unshift(newPost),
      error: err => this.errorMessage = err
    });
  }

  deletePost(id: number) {
    this.posts = this.posts.filter(p => p.id !== id);
    this.postService.deletePost(id).subscribe({
      error: err => {
        this.errorMessage = err;
        // rollback could be added
      }
    });
  }
}
